(()=>{'use strict';const choices=new Map();function draw(){const main=document.querySelector('#sceneMasterMain'),scene=typeof currentScene==='function'?currentScene():null;if(!main||!scene)return;document.getElementById('sceneStateReferences')?.remove();const states=(scene.reference_states||[]).filter(s=>s.status==='completed'&&s.image_url);if(!states.length)return;const card=main.children[1],preview=card?.querySelector('.scene-master-main-preview'),heading=card?.querySelector('.preview-head');if(!card||!preview||!heading)return;const key=data.project_id+'|'+(scene.scene_id||scene.id),master=selectedSceneVersion(scene,'master'),items=states.every(s=>s.contains_people===false)?states:[{state_id:'master',name:'空场景',image_url:master?.image_url},...states],nav=document.createElement('div');nav.id='sceneStateReferences';nav.style.cssText='display:flex;gap:10px;flex-wrap:wrap;margin:16px 0';const alternate=document.createElement('div');alternate.className='scene-master-main-preview';alternate.hidden=true;const info=document.createElement('p');info.className='subtle';const controls=[...card.children].filter(x=>x!==preview&&x!==heading);const select=heading.querySelector('select'),title=heading.querySelector('b');
function pick(id){const item=items.find(x=>x.state_id===id)||items[0],isMaster=item.state_id==='master';choices.set(key,item.state_id);preview.hidden=!isMaster;alternate.hidden=isMaster;controls.forEach(x=>x.hidden=!isMaster);if(select)select.hidden=!isMaster;if(title)title.textContent=scene.name+' · '+item.name;for(const b of nav.children){b.classList.toggle('primary',b.dataset.state===item.state_id);b.setAttribute('aria-pressed',String(b.dataset.state===item.state_id));}alternate.replaceChildren();if(!isMaster){const a=document.createElement('a');a.href=item.image_url;a.target='_blank';a.rel='noopener';const img=document.createElement('img');img.src=item.image_url;img.alt=item.name;a.append(img);alternate.append(a);info.textContent=item.contains_people===false?'无人背景布局 · 人物在生成分镜首帧时加入；不同布局只在入座或挪椅镜头切换':item.continuity_verified?'场景状态参考 · 桌椅与机位已校准':'历史含人物构图参考';}info.hidden=isMaster;}
for(const item of items){const b=document.createElement('button');b.type='button';b.dataset.state=item.state_id;b.style.cssText='display:flex;align-items:center;gap:8px;padding:8px 12px';const img=document.createElement('img');if(item.image_url)img.src=item.image_url;img.alt='';img.style.cssText='width:80px;height:45px;object-fit:contain;border-radius:4px;background:#080d14';b.append(img,document.createTextNode(item.name));b.onclick=()=>pick(item.state_id);nav.append(b);}preview.before(nav);preview.after(alternate,info);pick(choices.get(key)||'master');const label=main.children[0]?.querySelector('p');if(label&&label.textContent.includes('场景库'))label.textContent='场景库 / '+data.scenes.length+' · 本场景 '+items.length+' 种状态';}const old=renderScenes;renderScenes=function(){old();draw()};draw();})();
